import { useEffect, useState } from 'react';
import axios from '../../api/axiosInstance';

const Materials = () => {
    const [materials, setMaterials] = useState([]);
    const [search, setSearch] = useState('');
    const [form, setForm] = useState({
        name: '', category: '', unit: '', quantity: '',
        supplier: '', price: '', notes: '', image: null
    });
    const [editId, setEditId] = useState(null);

    const fetchMaterials = async () => {
        const res = await axios.get('/materials');
        setMaterials(res.data);
    };

    useEffect(() => { fetchMaterials(); }, []);

    const handleDelete = async (id) => {
        if (window.confirm('Xóa vật tư này?')) {
            await axios.delete(`/materials/${id}`);
            fetchMaterials();
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        const data = new FormData();
        Object.keys(form).forEach(k => {
            if (form[k]) data.append(k, form[k]);
        });

        if (editId) {
            await axios.put(`/materials/${editId}`, data);
            alert('Cập nhật thành công');
        } else {
            await axios.post('/materials', data);
            alert('Đã thêm mới');
        }

        fetchMaterials();
        setForm({ name: '', category: '', unit: '', quantity: '', supplier: '', price: '', notes: '', image: null });
        setEditId(null);
    };

    const handleEdit = (m) => {
        setForm({
            name: m.name, category: m.category, unit: m.unit,
            quantity: m.quantity, supplier: m.supplier,
            price: m.price, notes: m.notes, image: null
        });
        setEditId(m._id);
    };

    return (
        <div>
            <h2>📦 Quản lý Vật tư</h2>

            <input
                type="text"
                placeholder="Tìm vật tư..."
                onChange={(e) => setSearch(e.target.value)}
                style={{ marginBottom: '10px', padding: '8px', width: '300px' }}
            />

            <table border="1" cellPadding="10" width="100%">
                <thead>
                    <tr>
                        <th>Ảnh</th>
                        <th>Tên</th>
                        <th>Loại</th>
                        <th>ĐVT</th>
                        <th>Số lượng</th>
                        <th>Nhà cung cấp</th>
                        <th>Giá</th>
                        <th>Ghi chú</th>
                        <th>Hành động</th>
                    </tr>
                </thead>
                <tbody>
                    {materials.filter(m => m.name.toLowerCase().includes(search.toLowerCase())).map(m => (
                        <tr key={m._id}>
                            <td><img src={m.image} alt="" width="50" /></td>
                            <td>{m.name}</td>
                            <td>{m.category}</td>
                            <td>{m.unit}</td>
                            <td>{m.quantity}</td>
                            <td>{m.supplier}</td>
                            <td>{m.price?.toLocaleString()}đ</td>
                            <td>{m.notes}</td>
                            <td>
                                <button onClick={() => handleEdit(m)}>✏️</button>
                                <button onClick={() => handleDelete(m._id)}>🗑️</button>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>

            <hr style={{ margin: '40px 0' }} />
            <h3>{editId ? '🛠️ Cập nhật vật tư' : '➕ Thêm vật tư mới'}</h3>

            <form onSubmit={handleSubmit} encType="multipart/form-data">
                <input type="text" placeholder="Tên vật tư" required value={form.name}
                    onChange={e => setForm({ ...form, name: e.target.value })} /><br />

                <input type="text" placeholder="Loại" value={form.category}
                    onChange={e => setForm({ ...form, category: e.target.value })} /><br />

                <input type="text" placeholder="Đơn vị tính" value={form.unit}
                    onChange={e => setForm({ ...form, unit: e.target.value })} /><br />

                <input type="number" placeholder="Số lượng" value={form.quantity}
                    onChange={e => setForm({ ...form, quantity: e.target.value })} /><br />

                <input type="text" placeholder="Nhà cung cấp" value={form.supplier}
                    onChange={e => setForm({ ...form, supplier: e.target.value })} /><br />

                <input type="number" placeholder="Giá" value={form.price}
                    onChange={e => setForm({ ...form, price: e.target.value })} /><br />

                <textarea placeholder="Ghi chú" value={form.notes}
                    onChange={e => setForm({ ...form, notes: e.target.value })}></textarea><br />

                <input type="file" accept="image/*"
                    onChange={e => setForm({ ...form, image: e.target.files[0] })} /><br /><br />

                <button type="submit">{editId ? '💾 Lưu cập nhật' : '➕ Thêm mới'}</button>
            </form>
        </div>
    );
};

export default Materials;
